create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
do $$ declare tbl text; begin foreach tbl in array array['profiles','classes','competencies','learning_contents','activities','activity_attempts','challenges','student_progress','mastery_records','achievements','exams','exam_items','exam_attempts','projects','project_submissions','rubrics','assessments','music_compositions','music_events'] loop execute format('create trigger %I_updated_at before update on public.%I for each row execute function public.set_updated_at()', tbl, tbl); end loop; end $$;;
